// Review-time image decisions that create a NEW revision — never a silent
// rewrite of what the owner already accepted.
//
// Accepted generated bytes are immutable (the server refuses different bytes
// under a pinned id with `generated_image_immutable`). So when the accepted
// image is a PNG and the owner points the post at a JPEG-only destination
// (Instagram), the fix is a deliberate two-step:
//   1. "Prepare a JPEG copy": convert in a canvas and store it as a derived
//      asset (`saveDerivedGeneratedImage`) — nothing is accepted yet;
//   2. "Use the JPEG copy": a `saveRevision` pinning the derived id.
// And when the server cannot vouch for an accepted asset's provenance
// (`generated_image_review_required`), the owner re-accepts it explicitly.
//
// Destinations can be chosen after drafting, so the need is computed from the
// Review picker's current choice, not from the item's bindings at drawer open.

export const JPEG_ONLY_PROVIDERS = new Set(["instagram"]);

/** True when this post files a PNG generated image to at least one chosen JPEG-only destination. */
export function needsJpegCopy(item, { bindings = [], destinations = [], visualMode } = {}) {
  const mode = visualMode ?? item?.acceptedVisualMode;
  if (mode !== "ai_refinement") return false;
  if (item?.generatedImage?.ready !== true || item.generatedImage.mimeType !== "image/png") return false;
  return bindings.some((binding) =>
    destinations.some((destination) => (destination.destinationBinding ?? destination.binding) === binding && JPEG_ONLY_PROVIDERS.has(destination.provider)));
}

/** Browser conversion: decodes `url` and re-encodes it as JPEG bytes. */
export function convertImageUrlToJpeg(url, quality = 0.92) {
  return new Promise((resolve, reject) => {
    const probe = new Image();
    probe.onload = () => {
      const canvas = document.createElement("canvas");
      canvas.width = probe.naturalWidth;
      canvas.height = probe.naturalHeight;
      const context = canvas.getContext("2d");
      if (!context) { reject(new Error("no 2d context")); return; }
      context.drawImage(probe, 0, 0);
      canvas.toBlob((blob) => {
        if (!blob) { reject(new Error("canvas.toBlob returned no blob")); return; }
        blob.arrayBuffer().then((buffer) => resolve(new Uint8Array(buffer)), reject);
      }, "image/jpeg", quality);
    };
    probe.onerror = () => reject(new Error("generated image did not decode"));
    probe.src = url;
  });
}

const refused = (result) => !result || result.ok === false;
const messageOf = (result, fallback) =>
  (typeof result?.message === "string" && result.message) ||
  (Array.isArray(result?.issues) && result.issues.map((issue) => issue.message).join(" ")) ||
  fallback;

/**
 * deps: `{ rpc, loadImage(id) -> { url }, convert(url) -> Uint8Array, onChange() }`.
 * State per batch item: `{ status: "idle"|"preparing"|"ready"|"accepting"|"failed", derivedId, sourceMediaId, revision, message }`.
 * Every action is single-flight per post, so a double press never makes a
 * second derived asset or a second revision.
 */
export function createImageAcceptance({ rpc, loadImage, convert = convertImageUrlToJpeg, onChange = () => {} }) {
  const states = new Map();
  const set = (id, patch) => { states.set(id, { ...(states.get(id) ?? { status: "idle" }), ...patch }); onChange(id); };

  function state(id) {
    return states.get(id) ?? { status: "idle" };
  }

  /** A prepared copy only counts for the image and revision it was made from. */
  function preparedFor(item) {
    const entry = states.get(item.id);
    return entry?.derivedId && entry.sourceMediaId === item.generatedImage?.id && entry.revision === (item.revision ?? 0) ? entry : null;
  }

  async function prepare(item) {
    const current = state(item.id);
    if (current.status === "preparing" || current.status === "accepting") return current;
    if (preparedFor(item)) return state(item.id);
    const sourceMediaId = item.generatedImage?.id;
    if (!sourceMediaId) return current;
    set(item.id, { status: "preparing", message: null, derivedId: null, sourceMediaId, revision: item.revision ?? 0 });
    let url = null;
    try {
      ({ url } = await loadImage(sourceMediaId));
      const bytes = await convert(url);
      const derived = await rpc.saveDerivedGeneratedImage({ sourceMediaId, bytes, mimeType: "image/jpeg" });
      if (refused(derived) || !derived.id) {
        set(item.id, { status: "failed", message: messageOf(derived, null) });
      } else {
        set(item.id, { status: "ready", derivedId: derived.id });
      }
    } catch (error) {
      set(item.id, { status: "failed", message: error instanceof Error ? error.message : String(error) });
    } finally {
      if (url) URL.revokeObjectURL(url);
    }
    return state(item.id);
  }

  async function saveAcceptance(item, mediaId) {
    return rpc.saveRevision({
      batchItemId: item.id,
      expectedRevision: item.revision ?? 0,
      acceptedVisualMode: "ai_refinement",
      acceptedGeneratedMediaId: mediaId
    });
  }

  /** Accepts the prepared JPEG copy as a new revision. Returns the save result, or null when nothing was sent. */
  async function accept(item) {
    const entry = preparedFor(item);
    if (!entry || entry.status !== "ready") return null;
    set(item.id, { status: "accepting" });
    try {
      const saved = await saveAcceptance(item, entry.derivedId);
      if (refused(saved)) {
        set(item.id, { status: "ready", message: messageOf(saved, null) });
        return saved;
      }
      states.delete(item.id);
      onChange(item.id);
      return saved;
    } catch (error) {
      set(item.id, { status: "ready", message: error instanceof Error ? error.message : String(error) });
      return null;
    }
  }

  /** Re-accepts the currently pinned image (provenance review) as a new revision. */
  async function reaccept(item) {
    const current = state(item.id);
    if (current.status === "accepting" || !item.generatedImage?.id) return null;
    set(item.id, { status: "accepting", message: null });
    try {
      const saved = await saveAcceptance(item, item.generatedImage.id);
      if (refused(saved)) set(item.id, { status: "failed", message: messageOf(saved, null) });
      else { states.delete(item.id); onChange(item.id); }
      return saved;
    } catch (error) {
      set(item.id, { status: "failed", message: error instanceof Error ? error.message : String(error) });
      return null;
    }
  }

  return { state, prepare, accept, reaccept, needsJpegCopy };
}
